# ---- birth pool: traits (hand-authored) ------------------------------------------------
# effect helper
def lever(typ, verbs, when, tags=None):
    p = dict(type=typ, for_verbs=verbs, for_tags=tags or [], duration="permanent", applies_when=when)
    return dict(effect_id="eff.grant_lever", params=p)
def hazard(tags, when="hazard"):
    return dict(effect_id="eff.hazard_step", params=dict(ladder="severity", steps=-1, harm_tags=tags, applies_when=when))

